    "Busy on {servers}, and used here" : "Activo en {servers}, y usado aquí",
    "Busy on {servers}" : "Activo en {servers}",
    "bot" : "bot",
    "Failed to vote" : "No se ha podido votar",
    "Vote" : "Votar",
